SELECT s.schedule_id, s.schedule_name, s.cluster_name, s.frequency_description, s.expected_frequency_minutes, s.expected_freshness_sla, s.freshness_sla_minutes, s."priority", s.owner_contact, s.failure_action, s.monitoring_required, s.last_run_id, s.last_run_status, s.last_run_started_at, s.last_run_completed_at, s.last_success_at, s.last_failed_at, s.expected_step_count, s.successful_step_count, s.failed_step_count, s.failed_step, s.error_message, s.minutes_since_last_success, s.refresh_status, s.refreshed_at FROM dba_monitoring.v_redshift_scheduled_query_status s;	
